function qs(s,c=document){return c.querySelector(s)}function qsa(s,c=document){return [...c.querySelectorAll(s)]}
function linkMainCategories(){const cards=qsa('.category-card');if(cards.length!==MAIN_CATEGORIES.length)return;cards.forEach((card,index)=>{const item=MAIN_CATEGORIES[index];card.href=item.url;card.target='_blank';card.rel='noopener';card.setAttribute('aria-label',`${item.name} — open corresponding category on kakobuymake.com`);const icon=qs('.icon',card),title=qs('strong',card),description=qs('span:not(.icon)',card);if(icon)icon.textContent=item.icon;if(title)title.textContent=item.name;if(description)description.textContent=item.description})}
function renderProducts(items=PRODUCTS){const grid=qs('#productGrid');if(!grid)return;grid.innerHTML=items.map(p=>`<article class="product-card"><a class="product-media" href="${p.link}" target="_blank" rel="noopener"><img src="${p.img}" alt="${p.name} product image from kakobuymake.com" loading="lazy"></a><div class="product-body"><h3><a href="${p.link}" target="_blank" rel="noopener">${p.name}</a></h3><div class="product-meta"><span>${p.cat}</span><span>Selected from page ${p.page}</span></div><div class="product-price">$${Number(p.price).toFixed(2)}</div><div class="product-actions"><a class="btn btn-orange btn-small" href="${p.link}" target="_blank" rel="noopener">View product details ↗</a></div></div></article>`).join('');const empty=qs('#emptyState');if(empty)empty.style.display=items.length?'none':'block'}
function syncCategoryFilter(){const filter=qs('#categoryFilter');if(!filter)return;const current=filter.value;filter.innerHTML=['All',...MAIN_CATEGORIES.map(item=>item.name)].map(name=>`<option value="${name}">${name}</option>`).join('');if([...filter.options].some(option=>option.value===current))filter.value=current}
function syncLiveProductCopy(){const homeNote=qs('#products .fine');if(homeNote)homeNote.textContent='These 10 products were selected from pages 30 and 31 of kakobuymake.com and verified on September 23, 2026. Availability and prices can change on the main site.';if(location.pathname.startsWith('/spreadsheet/')){const intro=qs('.page-hero p'),footerNote=qs('.footer-note');if(intro)intro.textContent='Search 10 kakobuymake.com products selected from main-site pages 30 and 31. Every card uses the main product image and opens its corresponding detail page.';if(footerNote)footerNote.textContent='Product images, names, prices and detail links from pages 30 and 31 were verified against kakobuymake.com on September 23, 2026.'}}
function filterProducts(){const term=(qs('#productSearch')?.value||'').toLowerCase().trim();const cat=qs('#categoryFilter')?.value||'All';const items=PRODUCTS.filter(p=>(cat==='All'||p.cat===cat)&&(!term||`${p.name} ${p.cat}`.toLowerCase().includes(term)));renderProducts(items)}
function openQC(id){const p=PRODUCTS.find(x=>x.id===id);const modal=qs('#qcModal');if(!p||!modal)return;qs('#modalContent').innerHTML=`<div class="modal-grid"><img src="${p.img}" alt="${p.name} QC preview"><div><span class="eyebrow">QC snapshot</span><h2>${p.name}</h2><p><strong>${p.qc}</strong> · checked ${p.date}</p><p>Preview checklist: overall shape, visible stitching, material surface, color consistency, label alignment and obvious exterior defects.</p><div class="notice">This review is visual only. QC photos do not authenticate an item or test electronics, materials, durability or hidden construction.</div><div class="pill-row"><span class="pill">Shape</span><span class="pill">Stitching</span><span class="pill">Color</span><span class="pill">Labels</span></div><a class="btn btn-orange" href="/qc/">Open QC Center</a></div></div>`;modal.showModal();document.body.classList.add('modal-open')}
function setLanguage(lang){const d=I18N[lang]||I18N.en;localStorage.setItem('kako-lang',lang);document.documentElement.lang=lang==='zh'?'zh-CN':lang;qsa('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;if(d[k])el.textContent=d[k]});const input=qs('#productSearch');if(input)input.placeholder=d.search;const empty=qs('#emptyState');if(empty)empty.textContent=d.noResults}
function shippingEstimate(){const form=qs('#shippingForm'),result=qs('#shippingResult');if(!form||!result)return;const fd=new FormData(form),country=fd.get('country'),weight=Math.max(.1,Number(fd.get('weight'))||0),l=Number(fd.get('length'))||0,w=Number(fd.get('width'))||0,h=Number(fd.get('height'))||0;const volumetric=l&&w&&h?(l*w*h/6000):0;const bill=Math.max(weight,volumetric);let estimate;if(country==='US')estimate=20.73+18.5*bill;else if(country==='DE')estimate=8.76+14.5*bill;else estimate=null;if(!estimate){result.innerHTML='<p>A reliable sample rate is not yet published for this preview destination.</p><strong>Check live quote</strong><p>Use Kakobuy’s official calculator before submitting a parcel.</p>';return}const low=Math.max(1,estimate*.92),high=estimate*1.12;result.innerHTML=`<p>Indicative range</p><strong>$${low.toFixed(0)}–$${high.toFixed(0)}</strong><p>Billable weight: ${bill.toFixed(2)} kg${volumetric>weight?' (volume weight applies)':''}. Editorial estimate only; line eligibility and checkout price can differ.</p>`}
function convertLink(){const val=qs('#w2cInput')?.value.trim(),msg=qs('#w2cResult');if(!val||!/^https?:\/\//i.test(val)){if(msg)msg.innerHTML='<p>Paste a full Taobao, Weidian, 1688 or Tmall URL beginning with http.</p>';return}navigator.clipboard?.writeText(val);if(msg)msg.innerHTML='<p><strong>Link copied.</strong> Kakobuy will open in a new tab; paste the copied marketplace URL into its search field.</p><a class="btn btn-orange" href="https://www.kakobuy.com/" target="_blank" rel="noopener">Open Kakobuy</a>'}
document.addEventListener('click',e=>{const qc=e.target.closest('[data-qc]');if(qc)openQC(qc.dataset.qc);const faq=e.target.closest('.faq-button');if(faq){const item=faq.closest('.faq-item');const was=item.classList.contains('open');qsa('.faq-item.open').forEach(x=>{x.classList.remove('open');qs('.faq-button',x)?.setAttribute('aria-expanded','false')});if(!was){item.classList.add('open');faq.setAttribute('aria-expanded','true')}}if(e.target.closest('#menuBtn'))qs('#navLinks')?.classList.toggle('open');if(e.target.closest('[data-close-modal]')){qs('#qcModal')?.close();document.body.classList.remove('modal-open')}if(e.target.closest('#convertBtn'))convertLink()});
document.addEventListener('DOMContentLoaded',()=>{linkMainCategories();syncCategoryFilter();syncLiveProductCopy();renderProducts();qs('#productSearch')?.addEventListener('input',filterProducts);qs('#categoryFilter')?.addEventListener('change',filterProducts);const params=new URLSearchParams(location.search),query=params.get('q'),category=params.get('category');if(query&&qs('#productSearch'))qs('#productSearch').value=query;if(category&&qs('#categoryFilter'))qs('#categoryFilter').value=category;if(query||category)filterProducts();qs('#shippingForm')?.addEventListener('submit',e=>{e.preventDefault();shippingEstimate()});const lang=localStorage.getItem('kako-lang')||'en';const sel=qs('#languageSelect');if(sel){sel.value=lang;sel.addEventListener('change',e=>setLanguage(e.target.value))}setLanguage(lang);qs('#qcModal')?.addEventListener('close',()=>document.body.classList.remove('modal-open'))});

